if (event == "clickCustomButton") {
    let targetUrl = "";

    if (chapter && chapter.url) {
        try {
            let chUrl = String(chapter.url);
            let base64Str = chUrl.replace(/^data:chapterUrl;base64,/, '');
            let idx = base64Str.indexOf(',');
            if (idx >= 0) base64Str = base64Str.substring(0, idx);
            let params = JSON.parse(java.base64Decode(base64Str));
            if (params.commentUrl) {
                targetUrl = params.commentUrl;
            }
        } catch (e) {}
    } else if (book && book.tocUrl) {
        try {
            let tocUrl = String(book.tocUrl);
            let base64Str = tocUrl.replace(/^data:catalogUrl;base64,/, '');
            let idx = base64Str.indexOf(',');
            if (idx >= 0) base64Str = base64Str.substring(0, idx);
            let catalog = JSON.parse(java.base64Decode(base64Str));
            let source = catalog.source || "";
            let bookid = catalog.bookid || "";

            if (bookid) {
                let urlMap = {
                    "起点": "/qd_role?bookid=" + bookid,
                    "七猫小说": "/qm_comment?type=book&book_id=" + bookid,
                    "番茄小说": "/fq_comment?book_id=" + bookid,
                    "番茄听书": "/fq_comment?book_id=" + bookid,
                    "番茄畅听": "/fq_comment?book_id=" + bookid,
                    "番茄漫画": "/fq_comment?book_id=" + bookid
                };

                if (source == "晋江") {
                    let authorId = "";
                    try {
                        let jjUa = java.getWebViewUA() + '/JINJIANG-Android/513';
                        let resp = java.ajax('https://app-cdn.jjwxc.net/androidapi/novelbasicinfo?novelId=' + bookid + ',' + JSON.stringify({
                            headers: { 'User-Agent': jjUa }
                        }));
                        let info = JSON.parse(resp);
                        authorId = info.authorId || '';
                    } catch (e) {
                        authorId = '';
                    }
                    targetUrl = getServerHost() + "/jj_author?novelid=" + bookid + "&authorid=" + authorId;
                } else if (urlMap[source]) {
                    targetUrl = getServerHost() + urlMap[source];
                }
            }
        } catch (e) {}
    }

    if (targetUrl) {
        targetUrl += "&key=" + getSecretKey();
        java.showBrowser(
            targetUrl,
            null,
            "window.java=java;",
            JSON.stringify({
                "expandedCornersRadius": 20,
                "dismissOnTouchOutside": true,
                "isDraggable": true,
                "shouldDimBackground": true,
                "backgroundDimAmount": 0.5,
                "hardwareAccelerated": true,
                "isNestedScrollingEnabled": true,
                "isGestureInsetBottomIgnored": true,
                "setFitToContents": false,
                "heightPercentage": 0.8,
                "isHideable": true
            })
        );
    } else {
        java.toast("可能是不支持的来源，请等待目录加载完毕");
    }
    true;
}

