    s = (s == null) ? '' : String(s);
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function getTheme() {
    var h = [12, 28, 152, 168, 188, 205, 222, 248, 332][Math.floor(Math.random() * 9)];
    var s = 44 + Math.floor(Math.random() * 14);
    var l = 34 + Math.floor(Math.random() * 8);
    return `hsl(${h} ${s + 4}% ${l}%)`;
}

