        var c = colors[i % colors.length];


        var uPage = u + "?page=1";
        var action = encodeURIComponent(`java.open('explore', '${uPage}', '标签: ${nameEsc}');`);

        tagsHtml += `<a href="javascript:${action}" style="text-decoration:none; display:inline-flex; align-items:center; background:${c.bg}; border:1px solid ${c.bc}; color:${c.tc}; height:24px; padding:0 9px; border-radius:4px; font-size:12px; margin:0 6px 8px 0; white-space:nowrap; font-weight:500;">${t}</a>`;
        i++;
