    var rawTitle = String(r[3]).trim();


    var cleanTitle = rawTitle.replace(/\s*[（(][^）)]*[）)]/g, "").trim();
    var safeKeyword = cleanTitle.split("'").join("\\'");

    var rAction = encodeURIComponent(`java.open('search', '${safeKeyword}', '${safeKeyword}', '${safeSourceUrl}');`);

