function lgViewersCount(u,J){
  J=J||null; if(!J) return null;
  var id=u&&u.id; if(id==null) return null;
  var gmap={'female':'girls','male':'men','group':'couples','trans':'trans','couples':'couples','maleFemale':'couples'};
  var pg=gmap[(u.broadcastGender||u.gender||'')]||'girls';
  try{
    var ju=JSON.parse(String(J.ajax('https://zh.virtualtaboo.live/api/front/v4/models/search/group/username?query='+encodeURIComponent(u.username||'')+'&limit=20&offset=0&primaryTag='+pg+'&uniq=')));
    var arr=ju.models||[];
    for(var i=0;i<arr.length;i++){if(String(arr[i].id)===String(id)){if(arr[i].viewersCount!=null)return arr[i].viewersCount;break;}}
  }catch(e){}
  var tags=[pg];
  var all=['girls','couples','men','trans'];
  for(var t=0;t<all.length;t++){if(all[t]!==pg)tags.push(all[t]);}
  for(var k=0;k<tags.length;k++){
    try{
      var lj=JSON.parse(String(J.ajax('https://zh.virtualtaboo.live/api/front/models?removeShows=false&recInFeatured=false&limit=60&offset=0&primaryTag='+tags[k]+'&sortBy=stripRanking&userRole=user&sac=true&uniq=')));
      var ms=lj.models||[];
      for(var j=0;j<ms.length;j++){if(String(ms[j].id)===String(id))return ms[j].viewersCount;}
    }catch(e){}
  }
  return null;
}

