    loadTs().then(function(){
      var gt=0;function go(){ try{ window.turnstile.render(document.getElementById('cf'),{sitekey:key,callback:function(t){res(t);}}); }catch(e){ if(++gt<50) setTimeout(go,200); else rej(new Error('turnstile render fail')); } }
