function RG_S2B(s){ return new Packages.java.lang.String(String(s)).getBytes(RG_CS); }
function RG_H2B(h){ var s=''; for(var i=0;i<h.length;i+=2) s+=String.fromCharCode(parseInt(h.substr(i,2),16)); return RG_S2B(s); }
var RG_CONST = '4dd4c2e6b83162090e52b3c7a6733ba41cb2462b829ab58a196b39db57177524f49baf7f08e8d68d26a72e37c1a95a2f1f05a51892aef2949732b62a38aadd58';
// RG_B64 已移除（E版兼容）
function RG_b64d(s){
  var str=String(s||'').replace(/-/g,'+').replace(/_/g,'/');
  // ① android.util.Base64（LT版）
  try{
    var B=Packages.android.util.Base64;
    if(B && typeof B.decode==='function'){
      var r=B.decode(str,0);
      if(r && r.length>0) return r;
    }
  }catch(e){}
  // ② java.util.Base64（E版）
  try{
    var D=Packages.java.util.Base64.getDecoder();
    var r2=D.decode(str);
    if(r2 && r2.length>0) return r2;
  }catch(e2){}
  // ③ 纯 JS 兜底
  return RG_b64dJS(str);
}
function RG_b64dJS(str){
  var CH='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var out='';var buf=0,bits=0;
  var s=String(str);
  for(var i=0;i<s.length;i++){
    var c=s.charAt(i);
    if(c==='=')break;
    var v=CH.indexOf(c);
    if(v<0)continue;
    buf=(buf<<6)|v;bits+=6;
    if(bits>=8){bits-=8;out+=String.fromCharCode((buf>>bits)&255);}
  }
  var n=out.length;var arr=new Uint8Array(n);
  for(var k=0;k<n;k++)arr[k]=out.charCodeAt(k)&255;
  return arr;
}
function RG_spadeUrl(JV, b64, seedB64){
  var seedB = RG_b64d(seedB64);
  var raw = RG_b64d(b64);
  if (raw.length < 5) throw new Error('spade密文过短');
  if (RG_U8(raw,0)!==0xa8 || RG_U8(raw,2)!==0x01 || RG_U8(raw,3)!==0x00) throw new Error('spade头异常');
  var clen = Math.floor((raw.length-4)/16)*16;
  if (!clen) throw new Error('spade无完整块');
  var md1 = RG_MD.getInstance('SHA-512'); md1.update(seedB); var h1 = md1.digest();
  var md2 = RG_MD.getInstance('SHA-512'); md2.update(h1); md2.update(RG_H2B(RG_CONST)); var h2 = md2.digest();
  var keyB = RG_ARR.copyOfRange(h2,0,16), ivB = RG_ARR.copyOfRange(h2,16,32);
  var ctB = RG_ARR.copyOfRange(raw,4,4+clen);
  var c = RG_CIPHER.getInstance('AES/CBC/NoPadding');
  c.init(RG_CIPHER.DECRYPT_MODE, new RG_SK(keyB,'AES'), new RG_IVP(ivB));
  var pt = c.doFinal(ctB);
  var plen = pt.length;
  if (plen) { var pad = pt[plen-1]&255; if (pad>=1 && pad<=16 && pad<=plen) plen-=pad; }
  while (plen && (pt[plen-1]&255)===0) plen--;
  var s=''; for (var i=0;i<plen;i++) s+=String.fromCharCode(pt[i]&255);
  return s;
}
function RG_cencKey(JV, spadeB64){
  var raw = RG_b64d(String(spadeB64).replace(/-/g,'+').replace(/_/g,'/'));
  var len = raw.length;
  if (len < 3) throw new Error('spade_a过短');
  var v8 = len - (RG_U8(raw,0)^RG_U8(raw,1)^RG_U8(raw,2)) + 47;
  v8 = Math.min(v8, len-1);
  if (v8 < 33) throw new Error('spade_a长度无效');
  var work = [];
  for (var i=0;i<v8;i++) work.push(RG_U8(raw,1+i));
  var a=85,b=246;
  for (var i2=0;i2<v8;i2++){
    var old=work[i2], prev=(i2&1)?a:b;
    if (i2&1) a=old; else b=old;
    var pop=0,x=i2; while(x){pop+=x&1;x>>=1;}
    work[i2]=(-21-pop+(prev^old))&255;
  }
  var hs=''; for (var i3=1;i3<33;i3++) hs+=String.fromCharCode(work[i3]);
  return hs;
}
function RG_boxes(b,start,end){
  var o=[],p=start;
  while(p+8<=end){
    var sz=RG_U32(b,p), t=RG_STR(b,p+4,4), hdr=8;
    if(sz===1){ sz=RG_U32(b,p+8)*4294967296+RG_U32(b,p+12); hdr=16; }
    if(sz<hdr) break;
    o.push({t:t,p:p,s:sz,hdr:hdr}); p+=sz;
  }
  return o;
}
function RG_find(b,start,end,typ,acc){
  acc=acc||[];
  var bx=RG_boxes(b,start,end);
  for(var i=0;i<bx.length;i++){
    var x=bx[i];
    if(x.t===typ) acc.push(x);
    if('moov,trak,mdia,minf,stbl,dinf,edts,udta,stsd'.indexOf(x.t)>=0){
      RG_find(b,x.p+x.hdr,Math.min(x.p+x.s,b.length),typ,acc);
    }
  }
  return acc;
}
function RG_decrypt(bytes,keyHex){
