   try { if (!clickJava && QM_C_RUNTIME_JAVA && typeof QM_C_RUNTIME_JAVA.showBrowser == 'function') { clickJava = QM_C_RUNTIME_JAVA; clickSource = QM_C_RUNTIME_SOURCE || null; } } catch (e3) {}
   if (!clickJava) return false;
   runtime = {java:clickJava, source:clickSource};
   try { qmC_SetRuntime(clickJava, clickSource); } catch (e4) {}
   var html = qmC_CommentWindow.call(runtime, kind, bid, cid, pid, heading, paragraphText);
