    let link
    let settings = this.getFromCacheObject("FNSettings") || this.setDefaultSettings()
    if (!settings.DEBUG) link = this.getFromCache(urlIllustDetailed(illustId))

    if (!link) {
        let settings = this.getFromCacheObject("FNSettings") || this.setDefaultSettings()
        let urlMap = {
